                          "answer":  "A",
                          "key":  "|λE−A|=(λ−1)²−4=0 ⇒ λ−1=±2 ⇒ λ=3 或 −1。也可用 tr=2=3+(−1)、|A|=1−4=−3=3×(−1) 校验。错项：B 把 |A| 当成 3；C 用错对角线；D 符号错。",
                          "fix":  "二阶矩阵求特征值最快的写法：先用迹与行列式猜两个数，再代回验证。",
