                          "topic":  "大题第一问·切线斜率",
                          "stem":  "【大题第一问】设曲线由参数方程 x=t²、y=t³ 给出，则在 t=1 处该曲线的切线斜率 dy/dx=（　）\n（做完本题，当晚做该大题第二问：求该点处的曲率）",
                          "options":  [
                                          "A. 3/2",
                                          "B. 2/3",
                                          "C. 3",
                                          "D. 1/2"
                                      ],
                          "answer":  "A",
                          "key":  "dy/dt=3t²、dx/dt=2t，相除得 dy/dx=3t/2。代 t=1 得 3/2。错项：B 除反了；C 漏了分母的 2；D 把 t 也代错。",
                          "fix":  "参数方程求斜率：(dy/dt)÷(dx/dt)，约分后再代点，别先代再约。",
