                          "stem":  "【大题第一问】按扭转强度初估转轴最小直径，用 d≥A₀·(P/n)^{1/3}（A₀=112）。已知 P=5 kW、n=960 r/min，则 d 约为（　）\n（做完本题，当晚做该大题第二问：按弯扭合成强度校核该轴的危险截面）",
