                          "topic":  "真题2026",
                          "type":  "multi",
                          "stem":  "中国科学家发现，马铃薯中的 40%的基因来自番茄祖先“茄小姐”，另外 60%的基因则来自类马铃薯植物“薯先生”。这种杂交不仅形成了一个新物种，还催生出一个全新的器官——块茎。根据这一发现，科学家提出一条新的育种路径：利用番茄作为遗传底盘，导入块茎形成关键基因，培育出能“地下结土豆、地上长番茄”的新型作物。科学家能够利用基因技术进行新型作物的培育，是因为（　）",
