                          "type":  "text",
                          "kp":  "轴系结构改错",
                          "df":  108,
                          "df_src":  "manual",
                          "stem":  "某单级斜齿圆柱齿轮减速器输出轴轴系，设计者作了如下六项处理：\n① 齿轮与轴用平键连接，齿轮右侧靠轴肩定位，左侧由套筒顶紧，套筒另一端顶住轴承内圈；\n② 两支承均选用 30206 圆锥滚子轴承，内圈靠轴肩定位，两外圈两端单向固定，轴上未设游隙调整垫片；\n③ 定位轴肩高度取 5 mm，而 30206 轴承内圈挡边径向厚度为 5 mm；\n④ 轴承采用脂润滑，箱体内未设挡油环；\n⑤ 轴伸端采用唇形密封圈，唇口朝外（朝大气侧）；\n⑥ 轴肩过渡圆角半径取 2 mm，轴承内圈倒角半径 r=1.5 mm。\n问：指出上述处理中不合理之处（至少 4 处，指出 5 处得满分），并逐条说明正确做法与理由。",
                          "options":  [

                                      ],
                          "answer":  "正确项：①无错（套筒顶轴承内圈是标准做法）；答①为错项者该答案不计分，全题最高 12 分（5处×3分=15，占掉一个答案位最多答对4处）。\n错项 5 处（每处 3 分，须\"指出错项+正确做法+理由\"三要素齐）：\n② 圆锥滚子轴承两端固定却无游隙调整装置 → 端盖与箱体间加调整垫片（或螺钉调整）。30206 属可调游隙轴承，成对使用必须能调轴向游隙；过紧发热烧毁、过松振动。\n③ 轴肩高度＝内圈厚度(5mm) → 轴肩高度应小于内圈厚度(0.07–0.1d)，否则拆卸器钩不住内圈端面，内圈无法拆卸。\n④ 脂润滑无挡油环 → 设挡油环(封油环)。齿轮浸油润滑，飞溅稀油冲入轴承腔会稀释冲走润滑脂。\n⑤ 唇形密封圈唇口朝外 → 唇口应朝内(朝轴承侧)。介质压力越压越紧才密封；朝外则压力张开唇口而泄漏。\n⑥ 轴肩圆角 2mm \u003e 内圈倒角 1.5mm → 轴肩圆角半径应小于内圈倒角半径，否则圆角与倒角干涉，内圈贴不紧轴肩。",
                          "explain":  "考点：轴系结构改错（真题年年考、手机库原 0 道）。判据：游隙调整 / 轴肩与内圈厚度 / 挡油环 / 密封圈方向 / 圆角与倒角配合。",
