                          "stem":  "某轴系（一对 6206 深沟球轴承，齿轮浸油润滑），设计者作了如下六项处理：\n① 齿轮与轴用平键连接，键长等于齿轮轮毂长度；\n② 轴承内圈与轴采用 H7/g6 间隙配合；\n③ 两轴承外圈两端固定，箱体轴承座孔为通孔，不装端盖；\n④ 轴肩过渡圆角半径大于齿轮轮毂孔倒角半径；\n⑤ 套筒一端顶齿轮、另一端顶轴承外圈；\n⑥ 为传递更大转矩，采用两个平键，两键槽布置在轴的同一截面的同一母线上（圆周方位相同）。\n问：指出上述处理中不合理之处（至少 4 处，指出 5 处得满分），并逐条说明正确做法与理由。",
                          "options":  [

                                      ],
                          "answer":  "错项 6 处（答对任意 5 处即满分），每处 3 分：\n① 键长＝轮毂长度 → 键长应比轮毂短 2–5mm。键过长端部顶住、装配困难并产生应力集中。\n② 内圈与轴 H7/g6 间隙配合 → 应用过渡/过盈配合(k6/m6/n6)。间隙配合内圈相对轴颈转动(\"跑内圈\")，磨坏轴颈、发热。\n③ 外圈两端固定却不装端盖 → 必须装端盖压紧外圈并留调整垫片。否则外圈无轴向定位，轴系轴向窜动，齿轮啮合位置失控。\n④ 轴肩圆角 \u003e 轮毂孔倒角 → 轴肩圆角半径应小于轮毂孔倒角半径，否则干涉使齿轮端面贴不紧轴肩，轴向定位不可靠。\n⑤ 套筒顶轴承外圈 → 应顶内圈。顶外圈等于把活动件当定位件压，外圈失去固定且套筒随轴转，磨损发热。\n⑥ 两个平键布置在同一截面的同一母线 → 两平键应沿周向相隔 180° 布置。同截面同方位时两键槽削弱叠加在同一点、且两键挤压力同向产生附加弯矩；相隔 180° 后挤压力方向相反、不产生附加弯矩、对轴削弱均布。只有半圆键才放同一母线（半圆键槽深，同截面两侧布置会严重削弱轴）。",
                          "explain":  "考点：轴系结构改错（变体）。判据：键长 / 内圈配合 / 端盖轴向固定 / 圆角与倒角 / 套筒顶内圈 / 多键槽布置角度。",
                          "tags":  [
                                       "专业课",
                                       "轴系结构",
                                       "大题-每日"
                                   ],
                          "from_big":  false
