                          "kp":  "轴系结构改错",
                          "df":  100,
                          "df_src":  "manual",
                          "stem":  "某轴系，设计者作了如下六项处理：\n① 轴承内圈与轴采用普通螺纹连接；\n② 齿轮与轴用平键连接，键的上表面与轮毂槽底压紧、无间隙；\n③ 齿轮的轴向固定采用紧定螺钉；\n④ 轴承采用脂润滑，润滑脂填入量为轴承室空间的 90%；\n⑤ 轴伸端采用毛毡圈密封，毛毡圈内孔与轴留有 0.5 mm 间隙；\n⑥ 轴承定位轴肩高度取 0.15d。\n问：请指出上述处理中的所有不合理处，并逐条说明正确做法与理由。",
                          "options":  [

                                      ],
                          "answer":  "六处全部不合理（每处 2.5 分，六处共 15 分；只答 5 处得 12.5 分）\n① 内圈与轴用螺纹连接 → 应用过渡或过盈配合（k6/m6/n6）。轴承内圈必须与轴颈紧固成一体，螺纹连接无法保证同轴度与旋转精度且会松动。\n② 键上表面与轮毂槽底压紧 → 上表面与槽底之间必须留有间隙。平键靠两侧面传力，上表面为非工作面。\n③ 用紧定螺钉作轴向固定 → 应用轴肩、套筒、圆螺母、弹性挡圈等。紧定螺钉只能承受很小轴向力，且会在轴上打出凹坑，不能用于重要轴向定位。\n④ 脂填入量 90% → 填 1/3–1/2 轴承室空间。过多会搅油发热、脂变质流失，过少润滑不足。\n⑤ 毛毡圈与轴留 0.5 mm 间隙 → 应与轴保持适当过盈、紧贴轴颈。毛毡圈靠弹性压紧密封，有间隙即泄漏。\n⑥ 轴肩高度 0.15d → 取 (0.07–0.1)d 且低于内圈端面。过高则拆卸器钩不住内圈、与内圈挡边干涉；过低则定位面不足。",
                          "explain":  "六错全挑型（低一档、错得直白）。判据：内圈过盈、平键上表面留隙、紧定螺钉不承轴向力、脂量 1/3–1/2、毛毡圈紧贴、轴肩 0.07–0.1d。",
